            { "event": "upload", "oid": "bf3e3e2af9366a3b704ae0c31de5afa64193ebabffde2091936ad2e7510bc03a", "size": 346232,
            "action": { "href": "nfs://server/path", "header": { "key": "value" } } }"#;
